hp->free.pages = 4U;
hp->free.next = next;
next->free.pages = 3U;
next->free.next = NULL;
failed = chHeapIntegrityCheck(&test_heap);
*hp = saved;
test_assert(failed, "overlapping blocks accepted");
test_assert(!chHeapIntegrityCheck(&test_heap), "restored heap rejected");

