shared_code.value:
static ALIGNED_VAR(16) uint8_t core_buffer[64];

/* The real allocator is restored before unlocking or checking test results.
   No test assertion or rescheduling operation runs with the test arena
   installed.*/
static void *core_alloc(memgetfunc2_t allocp, size_t base, size_t top,
                        size_t size, unsigned align, size_t offset,
                        memcore_t *resultp) {
  memcore_t saved;
  void *p;

  chSysLock();
  saved = ch_memcore;
  ch_memcore.basemem = &core_buffer[base];
  ch_memcore.topmem = &core_buffer[top];
  p = allocp(size, align, offset);
  *resultp = ch_memcore;
  ch_memcore = saved;
  chSysUnlock();

  return p;
}

code.value:
p = core_alloc(chCoreAllocFromBaseI, 0U, 64U, SIZE_MAX,
               8U, 8U, &result);
test_assert(p == NULL, "oversized allocation accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 0U, 64U, 1U,
               8U, SIZE_MAX, &result);
test_assert(p == NULL, "oversized prefix accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 0U, 64U, 65U,
               1U, 0U, &result);
test_assert(p == NULL, "allocation beyond top accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 0U, 15U, 1U,
               16U, 1U, &result);
test_assert(p == NULL, "alignment beyond top accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[15], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 1U, 16U, 9U,
               8U, 0U, &result);
test_assert(p == NULL, "alignment padding ignored");
test_assert(result.basemem == &core_buffer[1], "base changed");
test_assert(result.topmem == &core_buffer[16], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 0U, 64U, 48U,
               16U, 9U, &result);
test_assert(p == &core_buffer[16], "wrong aligned pointer");
test_assert(result.basemem == &core_buffer[64], "wrong base");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 16U, 16U, 0U,
               16U, 0U, &result);
test_assert(p == &core_buffer[16], "zero-size allocation failed");
test_assert(result.basemem == &core_buffer[16], "base changed");
test_assert(result.topmem == &core_buffer[16], "top changed");

p = core_alloc(chCoreAllocFromBaseI, 16U, 16U, 1U,
               16U, 0U, &result);
test_assert(p == NULL, "empty arena allocation accepted");
test_assert(result.basemem == &core_buffer[16], "base changed");
test_assert(result.topmem == &core_buffer[16], "top changed");

p = core_alloc(chCoreAllocFromTopI, 0U, 64U, 8U,
               8U, SIZE_MAX - 7U, &result);
test_assert(p == NULL, "oversized prefix accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromTopI, 0U, 64U, SIZE_MAX,
               8U, 0U, &result);
test_assert(p == NULL, "oversized allocation accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromTopI, 0U, 64U, 1U,
               1U, 64U, &result);
test_assert(p == NULL, "prefix beyond base accepted");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[64], "top changed");

p = core_alloc(chCoreAllocFromTopI, 1U, 16U, 9U,
               8U, 0U, &result);
test_assert(p == NULL, "alignment below base accepted");
test_assert(result.basemem == &core_buffer[1], "base changed");
test_assert(result.topmem == &core_buffer[16], "top changed");

p = core_alloc(chCoreAllocFromTopI, 1U, 17U, 1U,
               8U, 16U, &result);
test_assert(p == NULL, "alignment padding ignored");
test_assert(result.basemem == &core_buffer[1], "base changed");
test_assert(result.topmem == &core_buffer[17], "top changed");

p = core_alloc(chCoreAllocFromTopI, 0U, 64U, 17U,
               16U, 32U, &result);
test_assert(p == &core_buffer[32], "wrong aligned pointer");
test_assert(result.basemem == &core_buffer[0], "base changed");
test_assert(result.topmem == &core_buffer[0], "wrong top");

p = core_alloc(chCoreAllocFromTopI, 16U, 16U, 0U,
               16U, 0U, &result);
test_assert(p == &core_buffer[16], "zero-size allocation failed");
test_assert(result.basemem == &core_buffer[16], "base changed");
test_assert(result.topmem == &core_buffer[16], "top changed");

p = core_alloc(chCoreAllocFromTopI, 16U, 16U, 1U,
               16U, 0U, &result);
test_assert(p == NULL, "empty arena allocation accepted");
test_assert(result.basemem == &core_buffer[16], "base changed");
test_assert(result.topmem == &core_buffer[16], "top changed");

shared_code.value:
static uint8_t area_buffer[64];

static bool intersection_matches(const memory_area_t *map1,
                                 const memory_area_t *map2,
                                 bool expected) {

  return (chMemIsAreaIntersectingX(map1, map2) == expected) &&
         (chMemIsAreaIntersectingX(map2, map1) == expected) &&
         (chMemIsSpaceIntersectingX(map1, map2->base,
                                   map2->size) == expected) &&
         (chMemIsSpaceIntersectingX(map2, map1->base,
                                   map1->size) == expected);
}

code.value:
map1.base = &area_buffer[16];
map1.size = 16U;
map2.base = &area_buffer[8];
map2.size = 32U;
test_assert(intersection_matches(&map1, &map2, true),
            "enclosure not symmetric");

map2.size = 16U;
test_assert(intersection_matches(&map1, &map2, true),
            "partial overlap missed");

map2 = map1;
test_assert(intersection_matches(&map1, &map2, true),
            "equal areas missed");

map2.base = &area_buffer[0];
map2.size = 8U;
test_assert(intersection_matches(&map1, &map2, false),
            "separated areas intersect");
map2.size = 16U;
test_assert(intersection_matches(&map1, &map2, false),
            "adjacent areas intersect");

map2.base = &area_buffer[31];
map2.size = 1U;
test_assert(intersection_matches(&map1, &map2, true),
            "last byte excluded");
map2.base = &area_buffer[32];
test_assert(intersection_matches(&map1, &map2, false),
            "following byte included");

map1.base = NULL;
map1.size = 0U;
map2.base = &area_buffer[16];
map2.size = 16U;
test_assert(intersection_matches(&map1, &map2, true),
            "whole space missed");
map2 = map1;
test_assert(intersection_matches(&map1, &map2, true),
            "whole spaces missed");

map2.size = 1U;
test_assert(intersection_matches(&map1, &map2, true),
            "address zero missed");

map1.base = (uint8_t *)(UINTPTR_MAX - 15U);
map1.size = 16U;
map2.base = (uint8_t *)(UINTPTR_MAX - 7U);
map2.size = 8U;
test_assert(intersection_matches(&map1, &map2, true),
            "upper boundary overlap missed");

map2.base = (uint8_t *)(UINTPTR_MAX - 31U);
map2.size = 16U;
test_assert(intersection_matches(&map1, &map2, false),
            "upper adjacent areas intersect");

map2.base = NULL;
map2.size = 0U;
test_assert(intersection_matches(&map1, &map2, true),
            "upper area missed by whole space");

local_variables.value:
const void *pointers[3];
memory_area_t map;
size_t max;

code.value:
pointers[0] = NULL;
pointers[1] = &area_buffer[1];
pointers[2] = NULL;
map.base = (uint8_t *)pointers;
map.size = sizeof pointers;
for (max = 0U; max < sizeof (void *); max++) {
  test_assert(chMemIsPointersArrayWithinX(&map, pointers, max) == 0U,
              "partial NULL pointer accepted");
}
test_assert(chMemIsPointersArrayWithinX(&map, pointers,
                                       sizeof (void *)) == sizeof (void *),
            "complete NULL pointer rejected");
test_assert(chMemIsPointersArrayWithinX(&map, pointers,
                                       SIZE_MAX) == sizeof (void *),
            "maximum budget rejected");

pointers[0] = &area_buffer[0];
for (max = 0U; max < sizeof pointers; max++) {
  test_assert(chMemIsPointersArrayWithinX(&map, pointers, max) == 0U,
              "pointer-array byte limit exceeded");
}

test_assert(chMemIsPointersArrayWithinX(&map, pointers,
                                       sizeof pointers) == sizeof pointers,
            "exact budget rejected");
test_assert(chMemIsPointersArrayWithinX(&map, pointers,
                                       sizeof pointers + 1U) == sizeof pointers,
            "larger budget rejected");
test_assert(chMemIsPointersArrayWithinX(&map, pointers,
                                       SIZE_MAX) == sizeof pointers,
            "maximum budget rejected");

test_assert(chMemIsPointersArrayWithinX(&map, &pointers[1],
                                       2U * sizeof (void *) - 1U) == 0U,
            "partial suffix terminator accepted");
test_assert(chMemIsPointersArrayWithinX(&map, &pointers[1],
                                       2U * sizeof (void *)) ==
            2U * sizeof (void *), "complete suffix rejected");

map.size = sizeof pointers - 1U;
test_assert(chMemIsPointersArrayWithinX(&map, pointers, SIZE_MAX) == 0U,
            "partial pointer outside area accepted");
map.size = sizeof pointers;
pointers[2] = &area_buffer[2];
test_assert(chMemIsPointersArrayWithinX(&map, pointers, SIZE_MAX) == 0U,
            "unterminated array accepted");

areas[0].base = (uint8_t *)text;
areas[0].size = sizeof text;
areas[1].base = (uint8_t *)-1;
areas[1].size = 0U;
test_assert(chMemIsStringWithinX(&areas[0], text, sizeof text) ==
            sizeof text, "string check unavailable or incorrect");
test_assert(chMemIsStringWithinX(&areas[0], text, sizeof text - 1U) == 0U,
            "short string budget accepted");

test_assert(chMemIsSpaceContainedX(areas, text, sizeof text),
            "area-table check unavailable or incorrect");
test_assert(!chMemIsSpaceContainedX(areas, text, sizeof text + 1U),
            "oversized area accepted");

test_assert(chMemIsSpaceReadableX(area_buffer, sizeof area_buffer, 1U),
            "readable fallback failed");
test_assert(chMemIsSpaceWritableX(area_buffer, sizeof area_buffer, 1U),
            "writable fallback failed");
test_assert(chMemIsAddressExecutableX(area_buffer),
            "executable fallback failed");

